using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.USR.Parentescos;using GraphApi.Services.USR.Parentescos;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.USR.Parentescos{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de Parentescos: creación, actualización y eliminación.")]    public class ParentescosMutation    {        [Authorize]        [GraphQLName("createParentescos")]        [GraphQLDescription("Crea un nuevo Parentesco usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadParentescos> CreateParentescosAsync(            [GraphQLDescription("Datos necesarios para crear el Parentesco.")]            clCreateParentescos objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de Parentesco.")]            IParentescosService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreateParentescos(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updateParentescos")]        [GraphQLDescription("Actualiza los campos especificados de un Parentesco existente.")]        public async Task<clReadParentescos?> UpdateParentescosAsync(            [GraphQLDescription("Datos del Parentesco a actualizar.")]            clUpdateParentescos objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de Parentesco.")]            IParentescosService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdateParentescos(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deleteParentescos")]        [GraphQLDescription("Elimina un Parentesco por su ID.")]        public async Task<bool> delParentescosAsync(            [GraphQLDescription("ID del Parentesco a eliminar.")]            int nParentescosID,            [Service]            [GraphQLDescription("Servicio para operaciones de Parentesco.")]            IParentescosService objService        )        {            return await objService.DeleteParentescos(nParentescosID);        }    }}